class Checker:
    def check(self, s, result):
        if not isinstance(s, str) or not isinstance(result, str):
            return False
        if len(s) < 2 or len(s) > 50 or len(s) % 2 != 0:
            return False
        if any(ch not in "01" for ch in s) or any(ch not in "01" for ch in result):
            return False
        if not self._is_special(s) or not self._is_special(result):
            return False
        if len(result) != len(s):
            return False
        expected = self._canonical(s)
        return expected is not None and result == expected

    def _is_special(self, s):
        balance = 0
        for ch in s:
            balance += 1 if ch == "1" else -1
            if balance < 0:
                return False
        return balance == 0

    def _canonical(self, s):
        if not s:
            return ""
        parts = []
        balance = 0
        start = 0
        for i, ch in enumerate(s):
            balance += 1 if ch == "1" else -1
            if balance < 0:
                return None
            if balance == 0:
                inner = self._canonical(s[start + 1:i])
                if inner is None:
                    return None
                parts.append("1" + inner + "0")
                start = i + 1
        if balance != 0 or start != len(s):
            return None
        parts.sort(reverse=True)
        return "".join(parts)

